/// <summary>
/// Receives AI count training samples from the handhelds into HSMobileOpsAiSample, the photo as
/// an attachment (DocumentManagement, document storage). Registered as HSMobileOpsAiSampleSvc.
/// </summary>
class HSMobileOpsAiSampleService
{
}

Method.Source:
/// <summary>
/// Stores one sample. Idempotent on SampleId; once an item has maxPerItem() samples further
/// ones are acknowledged but not stored, so storage stays bounded.
/// </summary>
public HSMobileOpsAiSampleResponse uploadSample(HSMobileOpsAiSampleRequest _request)
{
    HSMobileOpsAiSampleResponse response = new HSMobileOpsAiSampleResponse();
    HSMobileOpsAiSample         sample;
    HSMobileOpsAiSample         existing;
    System.IO.MemoryStream      stream;
    int                         rows;

    response.parmSuccess(false);
    response.parmStored(false);
    if (!_request || !_request.parmDataAreaId() || !_request.parmSampleId() || !_request.parmImageBase64()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }
    if (strLen(_request.parmImageBase64()) > HSMobileOpsAiSampleService::maxImageChars())
    {
        response.parmErrorCode('IMAGE_TOO_LARGE');
        return response;
    }

    changecompany (_request.parmDataAreaId())
    {
        select firstonly RecId from existing where existing.SampleId == _request.parmSampleId();
        if (existing.RecId)
        {
            response.parmSuccess(true);
            return response;
        }
        select count(RecId) from existing where existing.ItemId == _request.parmItemId();
        rows = existing.RecId;
        if (rows >= HSMobileOpsAiSample::maxPerItem())
        {
            response.parmSuccess(true);
            return response;
        }

        try
        {
        ttsbegin;
        sample.SampleId    = _request.parmSampleId();
        sample.ItemId      = _request.parmItemId();
        sample.Quantity    = _request.parmQuantity();
        sample.Corrections = _request.parmCorrections();
        sample.Annotation  = _request.parmAnnotation();
        sample.DeviceId    = _request.parmDeviceId();
        sample.UserName    = _request.parmUserName();
        sample.WarehouseId = _request.parmWarehouseId();
        sample.CapturedUtc = DateTimeUtil::utcNow();
        sample.insert();
        ttscommit;
        }
        catch (Exception::CLRError)
        {
            response.parmErrorCode('ERROR: ' + HSMobileOpsAiSampleService::clrMessage());
            return response;
        }
        catch
        {
            response.parmErrorCode('ERROR: ' + HSMobileOpsAiSampleService::lastInfolog());
            return response;
        }
    }

    // The photo: an attachment in document storage when it is available, otherwise in the
    // record itself, so a storage outage never loses the sample.
    changecompany (_request.parmDataAreaId())
    {
        if (!HSMobileOpsAiSampleService::attachPhoto(sample, _request.parmImageBase64()))
        {
            ttsbegin;
            sample.selectForUpdate(true);
            sample.ImageBase64 = _request.parmImageBase64();
            sample.update();
            ttscommit;
        }
    }

    response.parmStored(true);
    response.parmSuccess(true);
    return response;
}

private static boolean attachPhoto(HSMobileOpsAiSample _sample, str _base64)
{
    System.IO.MemoryStream stream;

    try
    {
        stream = new System.IO.MemoryStream(System.Convert::FromBase64String(_base64));
        DocumentManagement::attachFileToCommon(_sample, DocuType::typeFile(), stream,
            _sample.SampleId + '.jpg', 'image/jpeg', _sample.ItemId);
        return true;
    }
    catch (Exception::CLRError)
    {
        return false;
    }
    catch
    {
        return false;
    }
}

private static str lastInfolog()
{
    SysInfologEnumerator e = SysInfologEnumerator::newData(infolog.copy(1, infologLine()));
    str msg;

    while (e.moveNext())
    {
        msg = e.currentMessage();
    }
    return subStr(msg, 1, 200);
}

private static str clrMessage()
{
    System.Exception ex = CLRInterop::getLastException();
    str msg;

    if (ex)
    {
        msg = ex.get_InnerException() ? ex.get_InnerException().get_Message() : ex.get_Message();
    }
    return subStr(msg, 1, 200);
}

/// <summary>About 150 KB of JPEG - the app sends far less (640 px, quality 70).</summary>
private static int maxImageChars()
{
    return 200000;
}
